function validatePatrol(level: LevelData, entity: WorldEntity): void {
  const patrol = entity.patrol;
  if (!patrol) return;
  if (!(patrol.minX < patrol.maxX)) throw new Error(`patrol bounds are empty: ${entity.id}`);
